      acts: [['In Which the Day', 'Begins in the Wild'], ['In Which There Is', 'a Struggle for Survival'], ['In Which the Herd', 'Returns Home']],
      titles: ['Planet {G}', 'The Secret Life of the {G}', 'Wild {G}', 'The Wildlife of {S}'],
      coda: ["(whispering) And as darkness falls over {HOME}, the {PLAYER} returns to its nest, tired, happy, and slightly muddy. Remarkable.", "THE WHISPERING NATURALIST: (whispering) Thank you for joining us. The natural world is extraordinary. So, it turns out, are you."],
      quiz: [
        { q: "To watch wild creatures, you should...?", a: ['STAY QUIET', 'SHOUT', 'RUN AT THEM'], fact: "STAY QUIET and very still. Then they forget you're there." },
        { q: "A hide is for...?", a: ['WATCHING WILDLIFE', 'HIDE AND SEEK', 'SNACKS'], fact: "WATCHING WILDLIFE without being seen." },
        { q: "You find a baby bird on the ground. You...?", a: ['LEAVE IT BE', 'TAKE IT HOME', 'POKE IT'], fact: "Usually LEAVE IT BE. Its parents are probably nearby, watching." },
      ],
